INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Netzwerkkategorien immer nach Größe definiert werden. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Größe ist primärer Faktor"}, {"text": "Nein", "correct": false, "because": "Hauptsächlich nach Reichweite"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Netzwerkkategorien für ein IT-System analysiere?', 3, '[{"text": "Reichweite", "correct": true, "because": "Bestimmt Kategorie"}, {"text": "Schnellste Einrichtung", "correct": false, "because": "Struktur zählt"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Netzwerkkategorien gibt es?', 5, '[{"text": "LAN", "correct": true, "because": "Lokales Netzwerk"}, {"text": "WAN", "correct": true, "because": "Weitverkehrsnetzwerk"}, {"text": "Büronetzwerk", "correct": false, "because": "Keine Kategorie"}, {"text": "Farbnetzwerk", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein LAN ist ein lokales Netzwerk. b) Ein PAN ist für große Distanzen geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "PAN für kurze Reichweite"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Netzwerkkategorien für ein IT-System auswähle?', 4, '[{"text": "Reichweite", "correct": false, "because": "Definiert Kategorie"}, {"text": "Übertragungsrate", "correct": false, "because": "Beeinflusst Leistung"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Netzwerkkategorien nur für kabelgebundene Netzwerke gelten?', 2, '[{"text": "Nein", "correct": true, "because": "Auch drahtlos"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Wahl von Netzwerkkategorien?', 3, '[{"text": "Passende Reichweite", "correct": true, "because": "Sichert Verbindung"}, {"text": "Schnellste Einrichtung", "correct": false, "because": "Funktion zählt"}, {"text": "Weniger Kategorien", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale haben Netzwerkkategorien?', 5, '[{"text": "Geografische Reichweite", "correct": true, "because": "Definiert Typ"}, {"text": "Verbindungstyp", "correct": true, "because": "Kabel oder drahtlos"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein WAN verbindet große Distanzen. b) Ein MAN ist für persönliche Geräte gedacht. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "MAN für Städte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Netzwerkkategorien zu analysieren?', 4, '[{"text": "Reichweite", "correct": false, "because": "Definiert Kategorie"}, {"text": "Verbindungstyp", "correct": false, "because": "Beeinflusst Einsatz"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein LAN immer für große Distanzen geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Lokale Reichweite"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten verschiedene Netzwerkkategorien?', 4, '[{"text": "Skalierbarkeit", "correct": true, "because": "Passend für Größe"}, {"text": "Effizienz", "correct": true, "because": "Optimiert Verkehr"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Netzwerkkategorien nur für Unternehmen relevant sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch privat"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Netzwerkkategorien für ein IT-System auszuwählen?', 3, '[{"text": "Geografische Anforderungen", "correct": true, "because": "Bestimmt Typ"}, {"text": "Günstigste Lösung", "correct": false, "because": "Funktion wichtiger"}, {"text": "Bunte Kabel", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein PAN ist ein persönliches Netzwerk. b) Ein WAN ist für kurze Distanzen geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "WAN für große Distanzen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei Netzwerkkategorien?', 5, '[{"text": "Reichweite", "correct": true, "because": "Definiert Typ"}, {"text": "Bandbreite", "correct": true, "because": "Beeinflusst Leistung"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Netzwerkkategorien für ein IT-System plane?', 3, '[{"text": "Netzwerktyp", "correct": false, "because": "Definiert Einsatz"}, {"text": "Übertragungsrate", "correct": false, "because": "Bestimmt Leistung"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein MAN für persönliche Geräte geeignet?', 3, '[{"text": "Nein", "correct": true, "because": "Für städtische Netzwerke"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Netzwerkkategorien nur für drahtlose Netzwerke gelten?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kabelgebunden"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für Netzwerkkategorien?', 4, '[{"text": "Geografische Reichweite", "correct": true, "because": "Definiert Typ"}, {"text": "Schnellste Einrichtung", "correct": false, "because": "Funktion zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
